import{_ as t,o as a,c as i,a2 as e}from"./chunks/framework.CsGzzEsd.js";const b=JSON.parse('{"title":"JLPT N2 计划","description":"","frontmatter":{"title":"JLPT N2 计划"},"headers":[],"relativePath":"zh/blogs/JLPT-N2/plan.md","filePath":"zh/blogs/JLPT-N2/plan.md"}'),r={name:"zh/blogs/JLPT-N2/plan.md"};function d(o,l,h,n,s,u){return a(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="jlpt-n2-学习计划" tabindex="-1">JLPT N2 学习计划 <a class="header-anchor" href="#jlpt-n2-学习计划" aria-label="Permalink to &quot;JLPT N2 学习计划&quot;">​</a></h1><blockquote><p><strong>基本假设：</strong> 备考周期 24 周，每周约 <strong>7 小时</strong>。计划同时面向考试和真正有用的日语，所以阅读和听力始终与真实材料相连。</p></blockquote><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><ul><li>在语境中认出 N2 核心词汇和汉字，而不只是在单词卡上。</li><li>以明确的目的、结构图和可控的速度读完一篇 N2 长度的文章。</li><li>一遍听下来就能抓住主旨、立场和重要细节。</li><li>三次计时模拟考试均通过，且各部分得分和总分都高出合格线一定余量。</li></ul><h2 id="每周节奏" tabindex="-1">每周节奏 <a class="header-anchor" href="#每周节奏" aria-label="Permalink to &quot;每周节奏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>频率</th><th style="text-align:right;">时长</th><th>内容</th></tr></thead><tbody><tr><td>每天</td><td style="text-align:right;">20 分钟</td><td>间隔复习：词汇、汉字，并朗读一个例句。</td></tr><tr><td>每周 3 次</td><td style="text-align:right;">35 分钟</td><td>语法句型 → 与相近句型对比 → 8–12 道题。</td></tr><tr><td>每周 3 次</td><td style="text-align:right;">30 分钟</td><td>主动听力：先预测，听一遍，概括，再对照原文。</td></tr><tr><td>每周 2 次</td><td style="text-align:right;">45 分钟</td><td>计时阅读，然后分析结构和错误。</td></tr><tr><td>周末</td><td style="text-align:right;">90 分钟</td><td>各部分混合练习加每周复盘。</td></tr></tbody></table><h2 id="_24-周路线图" tabindex="-1">24 周路线图 <a class="header-anchor" href="#_24-周路线图" aria-label="Permalink to &quot;24 周路线图&quot;">​</a></h2><h3 id="第-1-阶段——基线与体系-第-1–2-周" tabindex="-1">第 1 阶段——基线与体系（第 1–2 周） <a class="header-anchor" href="#第-1-阶段——基线与体系-第-1–2-周" aria-label="Permalink to &quot;第 1 阶段——基线与体系（第 1–2 周）&quot;">​</a></h3><ul><li>做一套计时样题，覆盖语言知识、阅读和听力。</li><li>给错误分类：词汇、语法细微差别、句子衔接、阅读速度、漏听提示或注意力。</li><li>每项技能只选一门主课程或一本书，其余资料放进候选清单。</li><li>建立以例句为单位的复习卡组；控制新卡数量，使复习保持在 25 分钟以内。</li></ul><h3 id="第-2-阶段——覆盖-第-3–12-周" tabindex="-1">第 2 阶段——覆盖（第 3–12 周） <a class="header-anchor" href="#第-2-阶段——覆盖-第-3–12-周" aria-label="Permalink to &quot;第 2 阶段——覆盖（第 3–12 周）&quot;">​</a></h3><ul><li>每天学 12–15 个词汇和 4–6 个汉字，每周六天。</li><li>每周学 8–10 个语法句型，按对比组学习，如原因、让步、限定和倾向。</li><li>每天读一篇简短的真实文本：NHK 新闻、随笔、商品页面或职场通知。</li><li>每天听 15–20 分钟日语；其中三天对照原文做精听复播。</li></ul><p>每周日用本周的两个语法句型写一段 150–250 字的总结。</p><h3 id="第-3-阶段——速度与整合-第-13–18-周" tabindex="-1">第 3 阶段——速度与整合（第 13–18 周） <a class="header-anchor" href="#第-3-阶段——速度与整合-第-13–18-周" aria-label="Permalink to &quot;第 3 阶段——速度与整合（第 13–18 周）&quot;">​</a></h3><ul><li>从单独做题转向计时的阅读和听力套题。</li><li>阅读时标出作者的观点、转折词、指代对象和每段的作用。</li><li>听力时预判题型，只记下会改变答案的细节。</li><li>每周三次跟读一段 60–90 秒的音频，训练语音辨识和节奏。</li><li>维持旧词汇；如果回忆率低于 85%，减少新卡。</li></ul><h3 id="第-4-阶段——应试准备-第-19–23-周" tabindex="-1">第 4 阶段——应试准备（第 19–23 周） <a class="header-anchor" href="#第-4-阶段——应试准备-第-19–23-周" aria-label="Permalink to &quot;第 4 阶段——应试准备（第 19–23 周）&quot;">​</a></h3><ul><li>每个周末交替进行分项测试和整套模拟考试。</li><li>还原真实的时间、休息、音频播放和答题卡操作。</li><li>复盘每个干扰项为什么错，尤其是蒙对的题。</li><li>工作日每次只修补一项薄弱的子技能。</li></ul><h3 id="第-5-阶段——收尾-第-24-周" tabindex="-1">第 5 阶段——收尾（第 24 周） <a class="header-anchor" href="#第-5-阶段——收尾-第-24-周" aria-label="Permalink to &quot;第 5 阶段——收尾（第 24 周）&quot;">​</a></h3><ul><li>复习容易混淆的语法对、反复出错的汉字读音和听力提示词。</li><li>做简短的计时练习，不做耗尽体力的整套测试。</li><li>确认考试安排，保证睡眠。</li></ul><h2 id="每月真实场景检查" tabindex="-1">每月真实场景检查 <a class="header-anchor" href="#每月真实场景检查" aria-label="Permalink to &quot;每月真实场景检查&quot;">​</a></h2><p>每四周一次：</p><ul><li>读一篇文章，并用两分钟口头概括；</li><li>进行一次 20 分钟的对话或语言交换；</li><li>写一封简短的工作消息并请人修改；</li><li>记下应试学习提升了什么、没有提升什么。</li></ul><h2 id="前七天" tabindex="-1">前七天 <a class="header-anchor" href="#前七天" aria-label="Permalink to &quot;前七天&quot;">​</a></h2><ul><li>[ ] 完成基线样题并记录各部分得分。</li><li>[ ] 为每项技能选定一个核心资源。</li><li>[ ] 建立复习卡组和错题本。</li><li>[ ] 收藏三个可靠的阅读和听力来源。</li><li>[ ] 安排第一次 90 分钟的混合练习。</li></ul>',23)])])}const q=t(r,[["render",d]]);export{b as __pageData,q as default};
